def count_distinct_characters(string: str) -> int:
    # Step 1: Analyze the input
    string = string.lower()  # Convert the input string to lowercase to ignore case sensitivity

    # Step 2: Count unique characters
    unique_chars = set()
    for char in string:
        if char.isalpha():  # Check if the character is an alphabet
            unique_chars.add(char)

    # Step 3: Return the count
    return len(unique_chars)  # Return the size of the set as the number of distinct characters

